const babel = require('/exercise/node_modules/@babel/core');
const transformed = babel.transformFileSync('/exercise/binary.js', {
  cwd: '/exercise',
}).code;
const moduleObject = { exports: {} };
new Function('module', 'exports', transformed)(moduleObject, moduleObject.exports);
const { Binary } = moduleObject.exports;

const cases = [
  ['0', 0],
  ['1', 1],
  ['0000', 0],
  ['0000000101', 5],
  ['111111', 63],
  ['000100000000', 256],
  ['101010', 42],
  ['2', null],
  ['010201', null],
  ['10nope', null],
  ['nope10', null],
  ['10nope10', null],
  ['001nope', null],
  ['', null],
  [' ', null],
  ['10 ', null],
  [' 10', null],
  ['0b101', null],
  [null, null],
  [undefined, null],
  [101, null],
];

let failures = 0;
for (const [input, expected] of cases) {
  const actual = new Binary(input).toDecimal();
  if (!Object.is(actual, expected)) {
    failures += 1;
    console.error(`FAIL input=${JSON.stringify(input)} expected=${expected} actual=${actual}`);
  }
}

if (failures > 0) {
  process.exit(1);
}
console.log(`All ${cases.length} edge-case checks passed.`);
